}

/* Toggle switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-label input[type="checkbox"] {
    width: 2.5rem;
    height: 1.3rem;
    appearance: none;
    background: #ced4da;
    border-radius: 1rem;
    position: relative;
    cursor: pointer;
    transition: background 0.3s;
}

.toggle-label input[type="checkbox"]::before {
    content: '';
    position: absolute;
    width: 1rem;
    height: 1rem;
    background: #fff;
    border-radius: 50%;
    top: 0.15rem;
    left: 0.15rem;
    transition: transform 0.3s;
}

.toggle-label input[type="checkbox"]:checked {
    background: #0d6efd;
}

.toggle-label input[type="checkbox"]:checked::before {
    transform: translateX(1.2rem);
}

