.modal-dialog h4 {
    margin-bottom: 0.75rem;
}

.modal-dialog p {
    color: #555;
    margin-bottom: 1rem;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

/* Live preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 2px dashed #ced4da;
    border-radius: 8px;
    transition: all 0.3s;
}

.live-preview h4 {
    margin-bottom: 0.5rem;
}

.live-preview .preview-badge {
    display: inline-block;
    margin-top: 0.75rem;
    font-size: 0.8rem;
    color: #6c757d;
    padding: 0.25rem 0.5rem;
    background: #e9ecef;
    border-radius: 4px;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-badge {
    background: #333;
    color: #aaa;
}

.preview-system {
    background: #f5f5f5;
    color: #333;
}

.preview-font-small { font-size: 0.8rem; }
.preview-font-medium { font-size: 1rem; }
.preview-font-large { font-size: 1.2rem; }

.preview-compact {
    padding: 0.75rem;
    line-height: 1.2;
}

/* Loading */
.loading {
    text-align: center;
    padding: 3rem;
    color: #6c757d;
    font-size: 1.1rem;
}

